fn main(){tokio::runtime::Runtime::new().unwrap().block_on(async{
 let root=std::env::current_dir().unwrap().join("release/data/artwork");let db=game_storage::Storage::open(&root.parent().unwrap().join("database/gamedeck.db")).await.unwrap();let games=db.list_games().await.unwrap();let limit=std::sync::Arc::new(tokio::sync::Semaphore::new(2));let mut tasks=tokio::task::JoinSet::new();
 for game in games{let Some(path)=game.hero else{continue;};let root=root.clone();let limit=limit.clone();tasks.spawn(async move{let _permit=limit.acquire_owned().await.unwrap();tauri_free_warm(root,path,game.name).await});}
 let mut results=Vec::new();while let Some(result)=tasks.join_next().await{let row=result.unwrap();println!("{}: {}",results.len()+1,row["game"]);results.push(row);}
 std::fs::create_dir_all("docs/background-performance").unwrap();std::fs::write("docs/background-performance/result.json",serde_json::to_vec_pretty(&results).unwrap()).unwrap();println!("Display cache warmed for {} backgrounds",results.len());
});}
async fn tauri_free_warm(root:std::path::PathBuf,path:String,name:String)->serde_json::Value{tokio::task::spawn_blocking(move||{let start=std::time::Instant::now();match game_metadata::display::background(std::path::Path::new(&path),&root){Ok(display)=>{let cold_ms=start.elapsed().as_millis();let start=std::time::Instant::now();game_metadata::display::background(std::path::Path::new(&path),&root).unwrap();serde_json::json!({"game":name,"original_bytes":std::fs::metadata(path).unwrap().len(),"display_bytes":std::fs::metadata(display).unwrap().len(),"prepare_ms":cold_ms,"warm_ms":start.elapsed().as_micros() as f64/1000.0})},Err(error)=>serde_json::json!({"game":name,"error":error})}}).await.unwrap()}
